update(fn) {
  db.exec("BEGIN IMMEDIATE");
  try {
    const s = this.read();
    fn(s);
    s.revision++;
    db.prepare("UPDATE state SET value=? WHERE id=1")
      .run(JSON.stringify(s));
    db.exec("COMMIT");
    return s;
  } catch (e) {
    db.exec("ROLLBACK");
    throw e;
  }
}
